def shipping_zone(country_code):
    if country_code == "DE":
        return 1
    if country_code in ("FR", "NL"):
        return 2
    return 3


def shipping_cost(weight_kg, zone):
    bases = {1: 5.0, 2: 12.0, 3: 25.0}
    base = bases[zone]
    return round(base + 1.5 * weight_kg, 2)


def is_oversize(l, w, h):
    if max(l, w, h) > 120:
        return True
    return l + w + h > 300

import re


def bulk_discount(qty):
    if qty >= 100:
        return 0.12
    if qty >= 20:
        return 0.04
    return 0.0


def line_total(unit_price, qty):
    return round(unit_price * qty * (1 - bulk_discount(qty)), 2)


_SKU_RE = re.compile(r"^([A-Z]{2,4})/(\d{4})/([A-Za-z])$")


def parse_sku(s):
    if not isinstance(s, str):
        raise ValueError(f"invalid SKU: {s!r}")
    m = _SKU_RE.match(s)
    if not m:
        raise ValueError(f"invalid SKU: {s!r}")
    return {"category": m.group(1), "number": int(m.group(2)), "variant": m.group(3)}

